entries[20031] = { ["name"] = "Enchant Weapon - Superior Striking", ["text"] = "5 sec cast\nTools: Runed Arcanite Rod\nReagents:\nLarge Brilliant Shard (2), Greater Eternal Essence (10)\nPermanently enchant a Melee Weapon to do 5 additional points of damage." }
entries[20032] = { ["name"] = "Enchant Weapon - Lifestealing", ["text"] = "5 sec cast\nTools: Runed Arcanite Rod\nReagents:\nLarge Brilliant Shard (6), Essence of Undeath (6), Living Essence (6)\nPermanently enchant a melee weapon to often steal life from the enemy and give it to the wielder. Has a reduced effect for players above level 60." }
